from pathlib import Path

def replace_once(s, old, new, label):
    if old not in s:
        raise SystemExit(f'{label} target not found')
    return s.replace(old, new, 1)

# storage
p=Path('src/lib/storage.ts'); s=p.read_text()
if 'medLogItems?: Record<string, Record<string, string[]>>;' not in s:
    s=replace_once(s,
'''  medLogTimes: Record<string, Record<string, string>>;\n  /** Optional user note attached to a concrete scheduled medication slot. */\n  medLogNotes?: Record<string, Record<string, string>>;\n''',
'''  medLogTimes: Record<string, Record<string, string>>;\n  /** Optional user note attached to a concrete scheduled medication slot. */\n  medLogNotes?: Record<string, Record<string, string>>;\n  /** Granular taken items for a grouped scheduled medication slot. */\n  medLogItems?: Record<string, Record<string, string[]>>;\n''','storage type')
if '  medLogItems: {},' not in s:
    s=replace_once(s,'  medLogNotes: {},\n','  medLogNotes: {},\n  medLogItems: {},\n','storage empty')
if 'export function medScheduleItems' not in s:
    med='''export interface Med {\n  id: string;\n  name: string;\n  dose?: string;\n  times: string[];\n  asNeeded?: boolean;\n  color?: string;\n  note?: string;\n}\n'''
    s=replace_once(s,med,med+'''\n/** Existing grouped names (comma separated) can be tracked item-by-item. */\nexport function medScheduleItems(med: Pick<Med, "name">): string[] {\n  const items = med.name.split(",").map((item) => item.trim()).filter(Boolean);\n  return items.length ? items : [med.name.trim()].filter(Boolean);\n}\n''','med parser')
p.write_text(s)

# merge
p=Path('src/lib/merge.ts'); s=p.read_text()
if 'medLogItems: mergeStructured(' not in s:
    line='      medLogTimes: mergeMedLogTimes(effectiveLocal.medLogTimes, remote.medLogTimes),\n'
    if line not in s: raise SystemExit('merge medLogTimes line not found')
    s=s.replace(line,line+'''      medLogNotes: mergeStructured("medLogNotes", effectiveLocal.medLogNotes ?? {}, remote.medLogNotes ?? {}) as BixboData["medLogNotes"],\n      medLogItems: mergeStructured("medLogItems", effectiveLocal.medLogItems ?? {}, remote.medLogItems ?? {}) as BixboData["medLogItems"],\n''',1)
p.write_text(s)

# LogSheet
p=Path('src/components/LogSheet.tsx'); s=p.read_text()
if 'medScheduleItems,' not in s:
    s=replace_once(s,'  painColor,\n','  painColor,\n  medScheduleItems,\n','LogSheet import')
if 'const medItems = data.medLogItems?.[date] ?? {};' not in s:
    s=replace_once(s,
'''  const taken = data.medLog[date] ?? {};\n  const takenTimes = data.medLogTimes?.[date] ?? {};\n  const medNotes = data.medLogNotes?.[date] ?? {};\n''',
'''  const taken = data.medLog[date] ?? {};\n  const takenTimes = data.medLogTimes?.[date] ?? {};\n  const medNotes = data.medLogNotes?.[date] ?? {};\n  const medItems = data.medLogItems?.[date] ?? {};\n  const [editingScheduledKey, setEditingScheduledKey] = useState<string | null>(null);\n''','LogSheet state')
old='''                  const k = `${m.id}@${scheduledTime}`;\n                  const isTaken = !!taken[k];\n                  return (\n                    <label key={k} className="flex items-center gap-2 rounded-xl bg-surface px-2.5 py-2 ring-1 ring-border">\n                      <input type="checkbox" checked={isTaken} onChange={() => toggle(k, scheduledTime)} className="h-3.5 w-3.5 shrink-0" />\n                      <div className="min-w-0 flex-1">\n                        <p className="text-xs font-medium leading-tight">\n                          {m.name} <span className="text-[10px] font-normal text-muted-foreground">· scheduled {scheduledTime}</span>\n                        </p>\n                        {m.dose && <p className="text-[10px] leading-tight text-muted-foreground">{m.dose}</p>}\n                        {m.note && (\n                          <p className="text-[11px] text-muted-foreground">\n                            <Ico e="📝" size={13} /> <IcoText text={m.note} size={12} />\n                          </p>\n                        )}\n                      </div>\n                      {isTaken && (\n                        <Input\n                          type="time"\n                          value={takenTimes[k] ?? scheduledTime}\n                          onChange={(e) => setTakenTime(k, e.target.value)}\n                          className="h-7 w-20 px-2 text-xs"\n                          title={t("Actual time taken")}\n                        />\n                      )}\n                      <Input\n                        value={medNotes[k] ?? ""}\n                        onChange={(e) => setMedNote(k, e.target.value)}\n                        onClick={(e) => e.stopPropagation()}\n                        placeholder={t("Note (optional)")}\n                        className="h-7 min-w-0 flex-[0_1_125px] px-2 text-xs"\n                      />\n                    </label>\n                  );\n'''
new='''                  const k = `${m.id}@${scheduledTime}`;\n                  const isTaken = !!taken[k];\n                  const items = medScheduleItems(m);\n                  const grouped = items.length > 1;\n                  const selectedItems = medItems[k] ?? (isTaken ? items : []);\n                  const partial = grouped && selectedItems.length > 0 && selectedItems.length < items.length;\n                  return (\n                    <div key={k} className="rounded-xl bg-surface px-2.5 py-2 ring-1 ring-border">\n                      <div className="flex items-center gap-2">\n                        {grouped ? (\n                          <button type="button" onClick={() => setEditingScheduledKey(editingScheduledKey === k ? null : k)} className={`grid h-5 w-5 shrink-0 place-items-center rounded-md border text-[10px] font-bold ${selectedItems.length ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background text-muted-foreground"}`}>\n                            {selectedItems.length === items.length ? "✓" : selectedItems.length ? "–" : ""}\n                          </button>\n                        ) : (\n                          <input type="checkbox" checked={isTaken} onChange={() => toggle(k, nowHHMM())} className="h-3.5 w-3.5 shrink-0" />\n                        )}\n                        <button type="button" onClick={() => grouped && setEditingScheduledKey(editingScheduledKey === k ? null : k)} className="min-w-0 flex-1 text-left">\n                          <p className="text-xs font-medium leading-tight">{m.name} <span className="text-[10px] font-normal text-muted-foreground">· scheduled {scheduledTime}</span></p>\n                          {grouped && selectedItems.length > 0 && <p className="mt-0.5 text-[10px] leading-tight text-primary">{partial ? `${t("Taken")}: ${selectedItems.join(", ")}` : t("All taken")}</p>}\n                          {m.dose && <p className="text-[10px] leading-tight text-muted-foreground">{m.dose}</p>}\n                        </button>\n                        {isTaken && <Input type="time" value={takenTimes[k] ?? scheduledTime} onChange={(e) => setTakenTime(k, e.target.value)} className="h-7 w-20 px-2 text-xs" title={t("Actual time taken")} />}\n                      </div>\n                      {grouped && editingScheduledKey === k ? (\n                        <div className="mt-2 rounded-xl bg-tint/70 p-2 ring-1 ring-border/60">\n                          <p className="mb-1.5 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{t("What did you take?")}</p>\n                          <div className="space-y-1">\n                            {items.map((item) => {\n                              const checked = selectedItems.includes(item);\n                              return (\n                                <label key={item} className="flex items-center gap-2 rounded-lg bg-background/70 px-2 py-1.5 text-xs">\n                                  <input type="checkbox" checked={checked} onChange={() => {\n                                    const next = checked ? selectedItems.filter((x) => x !== item) : [...selectedItems, item];\n                                    update((d) => {\n                                      const day = { ...(d.medLog[date] ?? {}) };\n                                      const allItems = { ...(d.medLogItems?.[date] ?? {}) };\n                                      const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                                      if (next.length) { day[k] = true; allItems[k] = next; if (!times[k]) times[k] = nowHHMM(); }\n                                      else { delete day[k]; delete allItems[k]; delete times[k]; }\n                                      return { ...d, medLog: { ...d.medLog, [date]: day }, medLogItems: { ...(d.medLogItems ?? {}), [date]: allItems }, medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times } };\n                                    });\n                                  }} className="h-3.5 w-3.5" />\n                                  <span>{item}</span>\n                                </label>\n                              );\n                            })}\n                          </div>\n                          <Input value={medNotes[k] ?? ""} onChange={(e) => setMedNote(k, e.target.value)} placeholder={t("Note (optional)")} className="mt-2 h-7 px-2 text-xs" />\n                          <button type="button" onClick={() => setEditingScheduledKey(null)} className="mt-2 w-full rounded-lg bg-primary px-3 py-1.5 text-xs font-semibold text-primary-foreground">{t("Done")}</button>\n                        </div>\n                      ) : !grouped ? (\n                        <Input value={medNotes[k] ?? ""} onChange={(e) => setMedNote(k, e.target.value)} placeholder={t("Note (optional)")} className="mt-1.5 h-7 px-2 text-xs" />\n                      ) : null}\n                    </div>\n                  );\n'''
if 'const grouped = items.length > 1;' not in s:
    s=replace_once(s,old,new,'LogSheet scheduled row')
p.write_text(s)

# index overview
p=Path('src/routes/index.tsx'); s=p.read_text()
if 'medScheduleItems,' not in s:
    s=replace_once(s,'  painColor,\n','  painColor,\n  medScheduleItems,\n','index import')
if 'const items = { ...(d.medLogItems?.[date] ?? {}) };' not in s:
    old='''                        const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                        delete times[x.key];\n                        return {\n                          ...d,\n                          medLog: { ...d.medLog, [date]: day },\n                          medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times },\n                        };\n'''
    new='''                        const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                        delete times[x.key];\n                        const items = { ...(d.medLogItems?.[date] ?? {}) };\n                        delete items[x.key];\n                        return { ...d, medLog: { ...d.medLog, [date]: day }, medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times }, medLogItems: { ...(d.medLogItems ?? {}), [date]: items } };\n'''
    s=replace_once(s,old,new,'index uncheck')
if 'const all = medScheduleItems(x.med);' not in s:
    old='''                    {t("Taken")} · {actual ?? x.time} — {x.med.name}\n                    {x.med.dose ? ` (${x.med.dose})` : ""}\n                    {shifted && <span className="text-[10px] text-muted-foreground"> · {t("scheduled")} {x.time}</span>}\n                    <span className="text-[10px] text-muted-foreground"> · {t("tap to uncheck")}</span>\n'''
    new='''                    {(() => {\n                      const all = medScheduleItems(x.med);\n                      const selected = data.medLogItems?.[date]?.[x.key] ?? all;\n                      const omitted = all.filter((item) => !selected.includes(item));\n                      return <>\n                        {t("Taken")} · {actual ?? x.time} — {selected.join(", ")}\n                        {x.med.dose ? ` (${x.med.dose})` : ""}\n                        {shifted && <span className="text-[10px] text-muted-foreground"> · {t("scheduled")} {x.time}</span>}\n                        {omitted.length ? <span className="block text-[10px] text-destructive">{t("Not taken")}: {omitted.join(", ")}</span> : null}\n                        {data.medLogNotes?.[date]?.[x.key] ? <span className="block text-[10px] text-muted-foreground">{t("Note")}: {data.medLogNotes?.[date]?.[x.key]}</span> : null}\n                        <span className="text-[10px] text-muted-foreground"> · {t("tap to uncheck")}</span>\n                      </>;\n                    })()}\n'''
    s=replace_once(s,old,new,'index taken display')
p.write_text(s)
